WITH recent_orders AS (SELECT * FROM orders WHERE order_date BETWEEN '2023-06-01' AND '2025-10-01' AND customer_id IN (9, 14, 35)), channel_summary AS (SELECT channel, ROUND(STDDEV(shipping_fee), 2) AS stddev_shipping_fee, COUNT(discount) AS discount_count FROM recent_orders GROUP BY channel) SELECT channel, stddev_shipping_fee, discount_count FROM channel_summary ORDER BY discount_count DESC, channel LIMIT 1;
